// Basic UE 4.10 types used by the generated Sea of Thieves SDK.
// Generated by sot-dumper. Layout verified against the live game.
#pragma once

#include <cstddef>
#include <cstdint>
#include <cwchar>
#include <string>

namespace SoT
{
	// ---------------------------------------------------------------- containers
	template <typename T>
	struct TArray
	{
		T* Data;
		int32_t Num;
		int32_t Max;

		int32_t Count() const { return Num; }
		bool IsValidIndex(int32_t i) const { return i >= 0 && i < Num; }
		T& operator[](int32_t i) { return Data[i]; }
		const T& operator[](int32_t i) const { return Data[i]; }
		T* begin() { return Data; }
		T* end() { return Data + Num; }
		const T* begin() const { return Data; }
		const T* end() const { return Data + Num; }
	};

	struct FString : TArray<wchar_t>
	{
		std::wstring ToWString() const { return Data && Num > 0 ? std::wstring(Data, Num - 1) : std::wstring(); }
		std::string ToString() const
		{
			std::string out;
			for (int32_t i = 0; Data && i + 1 < Num; ++i)
				out.push_back(Data[i] < 0x80 ? static_cast<char>(Data[i]) : '?');
			return out;
		}
	};

	template <typename T>
	struct TEnumAsByte
	{
		uint8_t Value;
		operator T() const { return static_cast<T>(Value); }
	};

	template <typename T>
	struct TWeakObjectPtr
	{
		int32_t ObjectIndex;
		int32_t ObjectSerialNumber;
	};

	// ---------------------------------------------------------------------- names
	struct FNameEntry
	{
		void* HashNext;      // 0x00
		int32_t Index;       // 0x08  (comparison index << 1, bit 0 = wide)
		char AnsiName[1024]; // 0x0C

		bool IsWide() const { return Index & 1; }
		const char* GetAnsiName() const { return AnsiName; }
	};

	// FName in this build is {Number, Index}: the index lives in the HIGH dword.
	struct FName
	{
		int32_t Number;
		int32_t Index;

		bool operator==(const FName& o) const { return Number == o.Number && Index == o.Index; }
		std::string ToString() const;
	};

	// -------------------------------------------------------------------- objects
	class UClass;
	class UFunction;

	class UObject
	{
	public:
		void** VTable;         // 0x00
		UClass* Class;         // 0x08
		int32_t ObjectFlags;   // 0x10
		int32_t InternalIndex; // 0x14
		UObject* Outer;        // 0x18
		FName Name;            // 0x20

		std::string GetName() const;
		std::string GetFullName() const;
		bool IsA(const UClass* cls) const;
		void ProcessEvent(UFunction* function, void* params);

		static int32_t ObjectCount();
		static UObject* GetByIndex(int32_t index);
		static UObject* FindObject(const char* fullPath);
		template <typename T>
		static T* Find(const char* fullPath) { return static_cast<T*>(FindObject(fullPath)); }
	};
	static_assert(sizeof(UObject) == 0x28, "UObject layout");

	struct FUObjectItem
	{
		UObject* Object;
		int32_t Flags;
		int32_t ClusterRootIndex;
		int32_t SerialNumber;
	};
	static_assert(sizeof(FUObjectItem) == 0x18, "FUObjectItem layout");
}
